complete_selected_unit_objects.text:
def maximum_exp
  return minimum_exp_for_level(GrowthRate.max_level)
end

def add_exp(exp1, exp2)
  return (exp1 + exp2).clamp(0, maximum_exp)
end

def level=(value)
  if value < 1 || value > GameData::GrowthRate.max_level
    raise ArgumentError.new(_INTL("The level number ({1}) is invalid.", value))
  end
  @exp = growth_rate.minimum_exp_for_level(value)
  @level = value
end

def exp=(value)
  @exp = value
  @level = nil
end

def pbFaint(showMessage = true)
  if !fainted?
    PBDebug.log("!!!***Can't faint with HP greater than 0")
    return
  end
  return if @fainted   # Has already fainted properly
  @battle.pbDisplayBrief(_INTL("{1} fainted!", pbThis)) if showMessage
  PBDebug.log("[Pokémon fainted] #{pbThis} (#{@index})") if !showMessage
  @battle.scene.pbFaintBattler(self)
  @battle.pbSetDefeated(self) if opposes?
  pbInitEffects(false)
  # Reset status
  self.status      = :NONE
  self.statusCount = 0
  # Lose happiness
  if @pokemon && @battle.internalBattle
    badLoss = @battle.allOtherSideBattlers(@index).any? { |b| b.level >= self.level + 30 }
    @pokemon.changeHappiness((badLoss) ? "faintbad" : "faint")
  end
  # Reset form
  @battle.peer.pbOnLeavingBattle(@battle, @pokemon, @battle.usedInBattle[idxOwnSide][@index / 2])
  @pokemon.makeUnmega if mega?
  @pokemon.makeUnprimal if primal?
  # Do other things
  @battle.pbClearChoice(@index)   # Reset choice
  pbOwnSide.effects[PBEffects::LastRoundFainted] = @battle.turnCount
  if $game_temp.party_direct_damage_taken &&
     $game_temp.party_direct_damage_taken[@pokemonIndex] &&
     pbOwnedByPlayer?
    $game_temp.party_direct_damage_taken[@pokemonIndex] = 0
  end
  # Check other battlers' abilities that trigger upon a battler fainting
  pbAbilitiesOnFainting
  # Check for end of primordial weather
  @battle.pbEndPrimordialWeather
end

ItemHandlers::UseOnPokemonMaximum.add(:RARECANDY, proc { |item, pkmn|
  next GameData::GrowthRate.max_level - pkmn.level
})

def initialize(species, level, owner = $player, withMoves = true, recheck_form = true)
  species_data = GameData::Species.get(species)
  @species          = species_data.species
  @form             = species_data.base_form
  @forced_form      = nil
  @time_form_set    = nil
  self.level        = level
  @steps_to_hatch   = 0
  heal_status
  @gender           = nil
  @shiny            = nil
  @ability_index    = nil
  @ability          = nil
  @nature           = nil
  @nature_for_stats = nil
  @item             = nil
  @mail             = nil
  @moves            = []
  reset_moves if withMoves
  @first_moves      = []
  @ribbons          = []
  @cool             = 0
  @beauty           = 0
  @cute             = 0
  @smart            = 0
  @tough            = 0
  @sheen            = 0
  @pokerus          = 0
  @name             = nil
  @happiness        = species_data.happiness
  @poke_ball        = :POKEBALL
  @markings         = []
  @iv               = {}
  @ivMaxed          = {}
  @ev               = {}
  GameData::Stat.each_main do |s|
    @iv[s.id]       = rand(IV_STAT_LIMIT + 1)
    @ev[s.id]       = 0
  end
  case owner
  when Owner
    @owner = owner
  when Player, NPCTrainer
    @owner = Owner.new_from_trainer(owner)
  else
    @owner = Owner.new(0, "", 2, 2)
  end
  @obtain_method    = 0   # Met
  @obtain_method    = 4 if $game_switches && $game_switches[Settings::FATEFUL_ENCOUNTER_SWITCH]
  @obtain_map       = ($game_map) ? $game_map.map_id : 0
  @obtain_text      = nil
  @obtain_level     = level
  @hatched_map      = 0
  @timeReceived     = Time.now.to_i
  @timeEggHatched   = nil
  @fused            = nil
  @personalID       = rand(2**16) | (rand(2**16) << 16)
  @hp               = 1
  @totalhp          = 1
  calc_stats
  if @form == 0 && recheck_form
    f = MultipleForms.call("getFormOnCreation", self)
    if f
      self.form = f
      reset_moves if withMoves
    end
  end
end

def form=(value)
  oldForm = @form
  @form = value
  @ability = nil
  MultipleForms.call("onSetForm", self, value, oldForm)
  calc_stats
  $player&.pokedex&.register(self)
end

def calc_stats
  base_stats = self.baseStats
  this_level = self.level
  this_IV    = self.calcIV
  # Format stat multipliers due to nature
  nature_mod = {}
  GameData::Stat.each_main { |s| nature_mod[s.id] = 100 }
  this_nature = self.nature_for_stats
  if this_nature
    this_nature.stat_changes.each { |change| nature_mod[change[0]] += change[1] }
  end
  # Calculate stats
  stats = {}
  GameData::Stat.each_main do |s|
    if s.id == :HP
      stats[s.id] = calcHP(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id])
    else
      stats[s.id] = calcStat(base_stats[s.id], this_level, this_IV[s.id], @ev[s.id], nature_mod[s.id])
    end
  end
  hp_difference = stats[:HP] - @totalhp
  @totalhp = stats[:HP]
  self.hp = [@hp + hp_difference, 1].max if @hp > 0 || hp_difference > 0
  @attack  = stats[:ATTACK]
  @defense = stats[:DEFENSE]
  @spatk   = stats[:SPECIAL_ATTACK]
  @spdef   = stats[:SPECIAL_DEFENSE]
  @speed   = stats[:SPEED]
end

def has_flag?(flag)
  return @flags.any? { |f| f.downcase == flag.downcase }
end

complete_current_finite_receiver_units.complete_text:
attr_reader :hp

def hp=(value)
  @hp = value.to_i
  @pokemon.hp = value.to_i if @pokemon
end

def fainted?; return @hp <= 0; end

attr_reader :status

def status=(value)
  @effects[PBEffects::Truant] = false if @status == :SLEEP && value != :SLEEP
  @effects[PBEffects::Toxic]  = 0 if value != :POISON || self.statusCount == 0
  @status = value
  @pokemon.status = value if @pokemon
  self.statusCount = 0 if value != :POISON && value != :SLEEP
  @battle.scene.pbRefreshOne(@index)
end

attr_reader :statusCount

def statusCount=(value)
  @statusCount = value
  @pokemon.statusCount = value if @pokemon
  @battle.scene.pbRefreshOne(@index)
end

def pbUpdate(fullChange = false)
  return if !@pokemon
  @pokemon.calc_stats
  @level          = @pokemon.level
  @hp             = @pokemon.hp
  @totalhp        = @pokemon.totalhp
  if !@effects[PBEffects::Transform]
    @attack       = @pokemon.attack
    @defense      = @pokemon.defense
    @spatk        = @pokemon.spatk
    @spdef        = @pokemon.spdef
    @speed        = @pokemon.speed
    if fullChange
      @types      = @pokemon.types
      @ability_id = @pokemon.ability_id
    end
  end
end
